import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  onChange?: (date: Date | null) => void;
};

function startOfDay(date: Date): Date {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
}

function addDays(date: Date, days: number): Date {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

function isSameDay(a: Date | null, b: Date): boolean {
  return !!a && a.toDateString() === b.toDateString();
}

const quickOptions = [
  { label: 'Сегодня', getValue: () => startOfDay(new Date()) },
  { label: 'Вчера', getValue: () => addDays(startOfDay(new Date()), -1) },
  { label: 'Неделя назад', getValue: () => addDays(startOfDay(new Date()), -7) },
];

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [date, setDate] = useState<Date | null>(null);

  const handleChange = (value: Date | null) => {
    setDate(value);
    onChange?.(value);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
        {quickOptions.map((option) => {
          const optionValue = option.getValue();
          return (
            <JxChip
              key={option.label}
              active={isSameDay(date, optionValue)}
              onClick={() => handleChange(optionValue)}
            >
              {option.label}
            </JxChip>
          );
        })}
      </div>
      <JxCalendar locale="ru-RU" value={date} onValueChange={handleChange} />
    </div>
  );
}

